import {THEMES,resolveTheme,initializeTheme,chooseTheme} from './themes.js';
import {ownerAlternatives,selectCartOwner} from './ownership.js';
import {people,owners,PERMISSIONS,can,canVisit,requirePermission} from './access.js';
import {catalog,addCatalogOption,saveStaffPermissions} from './admin.js';
import {readBackup,backupSummary,MAX_BACKUP_BYTES} from './backup.js';
import {registerCaseGroups,setCatalogPrice,registerProduct} from './inventory-entry.js';
import {seriesFor,productIdentity,variantLabel,matchesProduct,filterCatalog,qualityName} from './catalog.js';
import {uid,stock,cost,makeSeed,saleTotal,saleProfit,inventoryValue,log,purchase} from './model.js';
import {ACCOUNTS,AUDIENCES,FLOW_KINDS,prepareState,localDate,priceRange,outsideRange,recordSale,repayDebt,returnSale,recordFlow,accountBalances,staffPayable,setRent,payRent,setOpeningBalances,addOpeningDebt,closeDay,reportWindow,inWindow,businessReport,debtReminders,disposeStock,eventTime,reverseMovement,canReverseMovement} from './business.js';

initializeTheme();

const KEY='telefonzona-v1',RECOVERY_KEY='telefonzona-before-restore';
let pendingBackup=null;
let state,storedRaw=null,loadFailed=false;
try {storedRaw=localStorage.getItem(KEY);state=JSON.parse(storedRaw)||makeSeed();if(state.version!==1||!Array.isArray(state.products)||!Array.isArray(state.sales))throw Error('Format');prepareState(state);}
catch {loadFailed=Boolean(storedRaw);state=prepareState(makeSeed());}
let TODAY=localDate();
let user='aziz',page='dashboard',period='month',owner='all',query='',category='all';
let brand='all',series='all',quality='all',audience='all',material='all',employee='all',salesIndex=0,catalogOwner='all';
let cart=[],saleAccount='till1',modal=false,online=navigator.onLine;
const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=value=>(value===0?0:Math.round(value)).toLocaleString('fr-FR').replaceAll('\u202f',' ');
const short=value=>Math.abs(value)>=1e6?(value/1e6).toFixed(2).replace('.',',')+' mln':money(value);
const name=id=>people(state).find(u=>u.id===id)?.name||id;
const accountName=id=>ACCOUNTS.find(([v])=>v===id)?.[1]||(id==='personal'?'O‘z cho‘ntagidan':id);
const audienceName=id=>AUDIENCES.find(([v])=>v===id)?.[1]||'';
const boss=()=>user==='aziz';
const allowed=permission=>can(state,user,permission);
const qualityLabel=id=>qualityName(id,state);
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',bag:'M5 7h14l1 14H4L5 7z M9 8V6a3 3 0 0 1 6 0v2',box:'m3 7 9-4 9 4v10l-9 4-9-4V7z M3 7l9 4 9-4 M12 11v10 M7 5l9 4',chart:'M4 20V10 M10 20V4 M16 20v-7 M22 20H2',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3a4 4 0 0 1 0 8',wallet:'M20 8V5H5a3 3 0 0 0 0 6h16v9H5a3 3 0 0 1-3-3V8 M16 14h5',down:'m8 10 4 4 4-4',arrow:'M5 12h14 m-5-5 5 5-5 5',up:'m7 17 10-10 M7 7h10v10',plus:'M12 5v14 M5 12h14',search:'M21 21l-5-5 M18 10a8 8 0 1 0-16 0 8 8 0 0 0 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',calendar:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4',check:'m5 12 4 4L19 6',close:'m6 6 12 12 M6 18 18 6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',download:'M12 3v12 m-4-4 4 4 4-4 M4 17v4h16v-4',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',alert:'m12 3 10 18H2L12 3z M12 9v5 M12 17h.01',receipt:'M5 3h14v19l-4-2-3 2-3-2-4 2V3z M8 8h8 M8 12h8 M8 16h5',return:'M3 10h11a6 6 0 1 1 0 12 M3 10l6-6 M3 10l6 6',logout:'M9 4H3v16h6 M12 12h10 m-4-4 4 4-4 4',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6l9-4z m-4 10 3 3 5-5',trash:'M3 6h18 M8 6V3h8v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',store:'M3 3h18l1 7H2l1-7z M4 10v11h16V10 M9 21v-7h6v7',filter:'M4 6h16 M7 12h10 M10 18h4',sun:'M12 3v2 M12 19v2 M3 12h2 M19 12h2 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0'};
const icon=(id,cls='')=>`<svg class="icon ${cls}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[id]||paths.box}"/></svg>`;
const pages={dashboard:'Umumiy ko‘rinish',pos:'Yangi sotuv',inventory:'Mahsulotlar',sales:'Sotuvlar tarixi',cash:'Kirim va chiqim',debts:'Qarzdorlar',employees:'Xodimlar',reports:'Hisobotlar',settings:'Sozlamalar',admin:'Boshqaruv'};
const options=(list,value)=>list.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('');
const button=(text,action,ic='plus',cls='primary',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${icon(ic)}${text}</button>`;
const empty=(title,sub='Boshqa filtrni tanlang yoki yangi ma’lumot qo‘shing.')=>`<div class="empty">${icon('box')}<b>${title}</b><p>${sub}</p></div>`;
const heading=(title,description,actions='')=>`<div class="page-heading"><div><div class="eyebrow">SAVDO NAZORAT OSTIDA</div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;
const badge=id=>`<span class="owner-badge ${id}"><i></i>${name(id)}</span>`;
function brandMark(id,compact=false){const b=catalog(state).brands.find(b=>b.id===id)||catalog(state).brands.at(-1);return `<span class="brand-logo brand-${b.id} ${compact?'compact-logo':''}">${esc(b.mark)}</span>`;}
function title(p){return [productIdentity(p).model||p.name,audienceName(p.audience),p.material,qualityLabel(p.quality)].filter(Boolean).join(' · ');}
function detail(p){return p.grouped?'Rang va naqshlar bir guruhda':variantLabel(p);}
function range(p){const [min,max]=priceRange(p);return min===max?money(max):money(min)+' – '+money(max);}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function mutate(fn){
  if(loadFailed)throw Error('Avvalgi ma’lumotni o‘qib bo‘lmadi. Avval zaxira nusxasini yuklab oling; eski yozuvlar ustiga yozilmadi.');
  const draft=structuredClone(state),before=draft.operations.length;
  const result=fn(draft);
  if(draft.operations.length===before)draft.operations.push({id:uid(),actor:user,kind:'catalog-or-settings',at:new Date().toISOString(),status:'local'});
  try{localStorage.setItem(KEY,JSON.stringify(draft));}catch{throw Error('Brauzerga saqlanmadi. Amal bajarilmadi; xotirani tekshiring yoki zaxira nusxasini oling.');}
  state=draft;return result;
}
function scope(extra={}){return {period,owner:boss()?owner:'all',seller:boss()?'all':user,...extra};}
function report(extra={}){return businessReport(state,scope(extra));}
function dateLabel(date){return new Date(date).toLocaleString('en-GB',{timeZone:'Asia/Tashkent',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).replaceAll('/','.');}
function periodBar(){const w=reportWindow(period);return `<div class="filter-bar"><div class="tabs">${[['today','Bugun'],['week','Hafta'],['month','Oy'],['year','Yil'],['all','Umumiy']].map(([id,label])=>`<button data-action="period" data-value="${id}" class="${period===id?'selected':''}">${esc(label)}</button>`).join('')}</div><div class="filter-right">${boss()&&page!=='employees'?`<label class="select-wrap">${icon('users')}<select id="owner-filter" aria-label="Mahsulot egasi">${options([['all','Barcha egalar'],...owners(state).map(o=>[o.id,o.name])],owner)}</select></label>`:''}<span class="date-range">${icon('calendar')}${period==='all'?'Barcha saqlangan yozuvlar':dateLabel(w.start)+' dan'}</span></div></div>`;}
function stat(label,value,ic,sub,featured=false,unit='so‘m',exact=false){return `<div class="stat-card ${featured?'featured':''}"><div class="stat-label">${label}<span class="stat-icon">${icon(ic)}</span></div><div class="stat-number">${exact?money(value):short(value)} <small>${unit}</small></div><div class="stat-bottom">${sub}</div></div>`;}
function render(){
  TODAY=localDate();
  if(!canVisit(state,user,page))page='dashboard';
  document.title=pages[page]+' — TelefonZona';
  const navItems=[['dashboard','grid'],['pos','bag'],['inventory','box'],['sales','receipt'],['cash','wallet'],['debts','clock'],['employees','users'],['reports','chart'],['admin','settings']].filter(([id])=>canVisit(state,user,id));
  const alerts=(allowed('debts')?debtReminders(state).length:0)+(boss()?state.notices.filter(n=>!n.read).length:0);
  $('#app').innerHTML=`<aside class="sidebar"><a href="#" class="brand" data-action="nav" data-page="dashboard"><span class="brand-mark">t<span>•</span></span>TelefonZona<span class="brand-dot">.</span></a><div class="shop-selector">${icon('store')}<div><b>${esc(state.settings.shop)}</b><small>Aksessuarlar do‘koni</small></div><span class="live-dot"></span></div><div class="nav-label">ISH MAYDONI</div><nav>${navItems.map(([id,ic])=>`<button class="nav-item ${page===id?'active':''}" data-action="nav" data-page="${id}" aria-label="${pages[id]}">${icon(ic)}<span>${id==='employees'&&!boss()?'Mening sotuvlarim':pages[id]}</span>${id==='pos'?'<span class="nav-plus">+</span>':''}${id==='debts'&&state.debts.some(d=>d.balance)?`<span class="nav-count">${state.debts.filter(d=>d.balance>0).length}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="demo-card"><b>${online?'Shu brauzerda saqlanadi':'Internet yo‘q · mahalliy rejim'}</b><p>${state.operations.length} ta yangi amal saqlangan.<br>Server hali ulanmagan.</p><span class="demo-pill">FRONTEND NAMUNA</span></div><button class="nav-item ${page==='settings'?'active':''}" data-action="nav" data-page="settings">${icon('settings')}Sozlamalar</button></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">Ish maydoni <span>/</span> <b>${pages[page]}</b></div><div class="top-actions"><button class="theme-trigger" data-action="themes" aria-label="Mavzuni tanlash" title="Mavzuni tanlash"><span class="theme-trigger-orbit" aria-hidden="true"></span><span class="theme-trigger-label">Mavzu</span></button><span class="connection ${online?'':'offline'}">${online?'Mahalliy demo':'Offline'}</span><button class="icon-btn notification" data-action="notifications" aria-label="Eslatmalar">${icon('bell')}${alerts?`<i></i>`:''}</button><div class="avatar">${people(state).find(u=>u.id===user).initials}</div><label class="role-switch"><span>Demo rolini almashtirish</span><select id="role">${options(people(state).map(u=>[u.id,u.name+' · '+u.role]),user)}</select></label></div></header><main>${({dashboard,pos,inventory,sales:salesPage,cash:cashPage,debts:debtsPage,employees,reports,settings,admin:adminPage})[page]()}</main><footer class="main-footer"><span>TelefonZona <b>•</b> Har bir savdo hisobda.</span><span>${TODAY} · UZS · Asia/Tashkent</span></footer></div>`;
}
function sellerHome(){
  return heading('Xayrli kun, '+esc(name(user)),'Otabek sizga ruxsat bergan amallarni shu yerdan bajaring.')+
    `<section class="panel seller-home"><div class="identity-card"><span class="avatar identity-avatar">${esc(people(state).find(p=>p.id===user).initials)}</span><div><h2>${esc(name(user))}</h2><p>Sotuvchi · o‘z mahsulotlari egasi</p></div></div>
    <div class="quick-actions">${allowed('sell')?button('Yangi sotuv','nav','bag','primary','data-page="pos"'):''}${allowed('inventory')?button('Mahsulot va qoldiq','nav','box','secondary','data-page="inventory"'):''}${allowed('cash')?button('Kirim / chiqim','nav','wallet','secondary','data-page="cash"'):''}${allowed('debts')?button('Qarz to‘lovi','nav','clock','secondary','data-page="debts"'):''}${button('O‘z cheklarim','nav','receipt','secondary','data-page="sales"')}</div>
    <p class="panel-copy">Har savdoda mahsulot egasi va pul tushgan kassa alohida qayd etiladi. Umumiy tushum, foyda va xodimlar hisobotini faqat Otabek ko‘radi.</p></section>`;
}
function adminPage(){
  bossGuard();
  const groups=[['categories','Mahsulot turlari','Masalan: Powerbank, Planshet aksessuarlari'],['materials','G‘ilof turlari','Masalan: Mat, Magnitli, Naqshli'],['qualities','Sifat guruhlari','Masalan: Original, Ekonom'],['brands','Brendlar','Masalan: Ugreen, Baseus']];
  return heading('Otabek boshqaruvi','Mahsulot turlari va xodim imkoniyatlarini o‘zingiz sozlang.')+
    `<div class="admin-overview"><div class="identity-card"><span class="avatar identity-avatar">OT</span><div><h2>Otabek</h2><p>Boshliq · barcha hisobotlar va sozlamalar</p></div></div><div><b>3 ta mahsulot egasi · 2 ta umumiy kassa</b><p>${owners(state).map(p=>esc(p.name)).join(', ')} mahsulotlari alohida sanaladi.</p></div></div>
    <section class="admin-section"><h2>Mahsulotlarni LEGO kabi tuzing</h2><p>Yangi tur qo‘shilgach, u mahsulot kiritish va qidiruvda darhol chiqadi. Eski qoldiq va cheklar saqlanadi.</p>
    <div class="admin-catalog-grid">${groups.map(([kind,label,hint])=>`<section class="panel catalog-setting"><div class="panel-heading"><h3>${label}</h3><span class="count-badge">${catalog(state)[kind].length}</span></div><div class="catalog-tags">${catalog(state)[kind].map(item=>`<span>${esc(typeof item==='string'?item:item.name)}</span>`).join('')}</div><form class="catalog-option-form" data-kind="${kind}"><label>Yangi nom<input name="name" aria-label="Yangi ${label.toLocaleLowerCase()} nomi" maxlength="60" placeholder="${hint}" required></label><div class="form-error" role="alert"></div><button type="submit" class="btn secondary">${icon('plus')}Qo‘shish</button></form></section>`).join('')}</div></section>
    <section class="admin-section"><h2>Xodimlar va ruxsatlar</h2><p>Faqat yoqilgan amallar xodimda ko‘rinadi va bajariladi. Mahsulot qo‘shish yoqilsa, kirim huquqi ham yoqiladi. Umumiy hisobotlar, foyda, zaxira va boshqaruv faqat Otabekda qoladi.</p>
    <div class="staff-permissions-grid">${people(state).filter(p=>p.id!=='aziz').map(person=>`<form class="panel staff-permissions-form" data-person="${person.id}" aria-label="${esc(person.name)} ruxsatlari"><div class="identity-card"><span class="avatar identity-avatar">${esc(person.initials)}</span><div><h3>${esc(person.name)}</h3><p>Sotuvchi · mahsulot egasi</p></div></div><label class="staff-name-field">Xodim ismi<input name="name" value="${esc(person.name)}" maxlength="60" required></label><div class="permission-list">${PERMISSIONS.map(p=>`<label class="permission-toggle"><span>${esc(p.label)}</span><input type="checkbox" name="${p.id}" ${can(state,person.id,p.id)?'checked':''} aria-label="${esc(person.name+' — '+p.label)}"><span class="toggle-track" aria-hidden="true"></span></label>`).join('')}</div><div class="locked-report">${icon('shield')}Umumiy hisobotlar: faqat Otabek</div><div class="form-error" role="alert"></div><button type="submit" class="btn primary">${icon('check')}Ruxsatlarni saqlash</button></form>`).join('')}</div></section>
    <div class="info-banner section-gap">${icon('shield')}<span>Bu frontenddagi amallar ruxsati. Haqiqiy shaxsiy kirish va serverdagi himoya hali ulanmagan; demo rolini almashtirish login emas.</span></div>`;
}
function dashboard(){
  if(!boss())return sellerHome();
  const m=report(),low=state.products.filter(p=>stock(p)<=p.min),balances=accountBalances(state);
  return heading(`Xayrli kun, ${name(user)}`,boss()?'Savdo, qoldiq va pul harakati — bir qarashda.':'Sotuvlaringiz va do‘kondagi mavjud mahsulotlar.',button('Yangi sotuv','nav','plus','primary','data-page="pos"'))+periodBar()+`<div class="stats-grid">${stat('Savdo summasi',m.revenue,'wallet',`${m.count} ta chek · nasiya bilan birga`,true)}${boss()?stat('Yalpi foyda',m.gross,'chart','Savdo − sotilgan mahsulot tannarxi'):stat('Cheklar',m.count,'receipt','O‘zingiz rasmiylashtirgan sotuvlar',false,'ta')}${stat('Sotilgan mahsulot',m.units,'box','Qaytarishlar hisobga olingan',false,'dona')}${boss()?stat('Sof natija',m.net,'chart',m.rentIncluded?'Kiritilgan xarajatlar va ijara ayrilgan':'Ijara ayrilmagan'):stat('Menga qaytariladigan pul',staffPayable(state,user),'wallet','O‘z cho‘ntagingizdan qilgan chiqimlar')}</div>
<div class="dashboard-grid"><section class="panel chart-panel"><div class="panel-heading"><div><h2>${boss()?'Pul va savdo alohida hisobda':'Tezkor amallar'}</h2><p>Mahsulot egasi, sotuvchi va kassa alohida yoziladi</p></div>${icon('shield')}</div>${boss()?`<div class="balance-list">${ACCOUNTS.map(([id,label])=>`<div><span>${label}</span><b>${money(balances[id])} <small>so‘m</small></b></div>`).join('')}<div><span>Xaridorlardan olinadigan qarz</span><b>${money(state.debts.reduce((sum,d)=>sum+d.balance,0))} <small>so‘m</small></b></div></div>`:'<p class="panel-copy">Kelishilgan narxni yozing. Qaysi kassaga pul olinganini tanlang. Nasiya va narxdan tashqari sotuvda izoh qoldiring.</p>'}<div class="quick-actions">${button('Kirim / chiqim','flow','wallet','secondary')}${button('Qarzdorlar','nav','clock','secondary','data-page="debts"')}${boss()?button('Kunni yopish','close-day','check','secondary'):''}</div></section><section class="panel stock-alert"><div class="panel-heading"><div><h2>Kam qolgan mahsulotlar</h2><p>Takroriy xaridni oldindan rejalang</p></div><span class="count-badge">${low.length}</span></div>${low.slice(0,4).map(p=>`<button class="low-item" data-action="find-product" data-id="${p.id}"><span class="product-thumb">${brandMark(productIdentity(p).brand,true)}</span><span class="low-text"><b>${esc(title(p))}</b><small>${esc(p.name)} · ${name(p.owner)}</small></span><span class="stock-number">${stock(p)}<small>dona</small></span></button>`).join('')||empty('Qoldiq yetarli')}<button class="text-link" data-action="lowstock">Barcha kam qoldiqlar ${icon('arrow')}</button></section></div>
${boss()&&debtReminders(state).length?`<div class="info-banner section-gap">${icon('bell')}<span><b>${debtReminders(state).length} ta qarzning muddati keldi.</b> Qarzdorlar bo‘limida telefon va qolgan summa tayyor.</span>${button('Ko‘rish','nav','arrow','secondary','data-page="debts"')}</div>`:''}<section class="panel section-gap"><div class="panel-heading"><div><h2>So‘nggi sotuvlar</h2><p>Haqiqiy sotilgan narx va to‘lov holati</p></div>${button('Barchasi','nav','arrow','secondary','data-page="sales"')}</div>${salesTable(filteredSales().slice(0,5))}</section>` ;
}
function searchbar(placeholder='Model yoki mahsulotni qidiring…'){return `<label class="search-field">${icon('search')}<input id="search" value="${esc(query)}" aria-label="${placeholder}" placeholder="${placeholder}" autocomplete="off"></label>`;}
function visibleProducts(){return filterCatalog(state.products,{brand,series,query,category,quality}).filter(p=>(audience==='all'||p.audience===audience)&&(material==='all'||p.material===material)&&(catalogOwner==='all'||p.owner===catalogOwner));}
function catalogFilters(){
  const list=seriesFor(brand),b=catalog(state).brands.find(b=>b.id===brand);
  return `<section class="catalog-browser"><div class="catalog-filter-heading"><b>Brend → seriya → model</b><button class="small-link" data-action="catalog-reset">Filtrlarni tozalash</button></div><div class="brand-grid" aria-label="Brendlar"><button class="brand-card ${brand==='all'?'selected':''}" data-action="brand" data-value="all"><span class="all-brands">Hammasi</span><small>${state.products.length} guruh</small></button>${catalog(state).brands.map(b=>`<button class="brand-card ${brand===b.id?'selected':''}" data-action="brand" data-value="${b.id}">${brandMark(b.id)}<span>${esc(b.name)}</span></button>`).join('')}</div>${list.length?`<div class="series-header"><b>${b.name} seriyalari</b><span>Qidiruvdan to‘g‘ridan-to‘g‘ri ham topasiz</span></div><div class="series-grid"><button class="series-card ${series==='all'?'selected':''}" data-action="series" data-value="all"><b>Hammasi</b></button>${list.map(s=>`<button class="series-card ${series===s.id?'selected':''}" data-action="series" data-value="${s.id}"><b>${s.name}</b><small>${s.hint}</small></button>`).join('')}</div>`:''}${searchbar('Modelni qidiring: S23, S23+, S23U, iPhone 15PM…')}<div class="search-caption"><span><b>${visibleProducts().length} ta guruh</b> topildi</span><span>Plus = + · Ultra = U · Pro = P · Pro Max = PM</span></div></section>
<div class="category-tabs">${[['all','Barchasi'],...catalog(state).categories.map(c=>[c,c])].map(([id,label])=>`<button data-action="category" data-value="${id}" class="${category===id?'selected':''}">${esc(label)}</button>`).join('')}</div>
<div class="flat-filters"><label>Mahsulot egasi<select id="catalog-owner">${options([['all','Uchala egasi'],...owners(state).map(o=>[o.id,o.name])],catalogOwner)}</select></label><label>Kim uchun<select id="audience-filter">${options([['all','Barchasi'],...AUDIENCES],audience)}</select></label><label>G‘ilof turi<select id="material-filter">${options([['all','Barchasi'],...catalog(state).materials.map(m=>[m,m])],material)}</select></label><label>Sifat<select id="quality-filter">${options([['all','Barchasi'],...catalog(state).qualities.map(t=>[t.id,t.name])],quality)}</select></label></div>`;
}
function productCard(p){const available=stock(p),inCart=cart.find(r=>r.productId===p.id)?.qty||0;return `<button class="product-card simple-product" data-action="add-cart" data-id="${p.id}" ${available<=inCart?'disabled':''} aria-label="${esc(title(p)+' · '+p.name+' · egasi '+name(p.owner))} savatga qo‘shish"><div class="product-card-top">${brandMark(productIdentity(p).brand)}<span class="stock-label ${available<=p.min?'low':''}">${available} dona</span></div><div class="product-meta">${p.quality?`<span class="quality-badge quality-${esc(p.quality)}">${esc(qualityLabel(p.quality))}</span>`:''}<b class="model-name">${esc(productIdentity(p).model||p.name)}</b><span class="accessory-name">${esc([audienceName(p.audience),p.material||p.name].filter(Boolean).join(' · '))}</span><p>${esc(detail(p))}</p><span class="card-owner">${name(p.owner)}</span><div><strong>${range(p)} <small>so‘m</small></strong><span class="card-add">+</span></div>${p.minPrice===undefined?'<small class="range-unset">Narx oralig‘i hali belgilanmagan</small>':''}</div></button>`;}
function addCart(id){requirePermission(state,user,'sell');const p=state.products.find(p=>p.id===id),row=cart.find(r=>r.productId===id);if(!p||(row?.qty||0)>=stock(p))throw Error('Omborda yetarli mahsulot yo‘q.');if(row)row.qty++;else cart.push({productId:id,owner:p.owner,qty:1,price:p.price});render();}
function cartItem(row){const p=state.products.find(p=>p.id===row.productId);return `<div class="cart-item"><div class="cart-info"><b>${esc(title(p))}</b><small>${esc(p.name)} · ${name(p.owner)}</small><label class="cart-owner-selector">Mahsulot egasi<select data-cart-owner="${p.id}" aria-label="Mahsulot egasi: ${esc(title(p))}">${owners(state).map(o=>{const alternatives=ownerAlternatives(state,p).filter(x=>x.owner===o.id),qty=alternatives.reduce((sum,x)=>sum+stock(x),0);return `<option value="${o.id}" ${o.id===p.owner?'selected':''} ${qty<row.qty?'disabled':''}>${esc(o.name)} · ${qty} dona${qty<row.qty?' · qoldiq yetmaydi':''}</option>`;}).join('')}</select></label><div class="cart-controls"><div class="stepper"><button data-action="cart-minus" data-id="${p.id}" aria-label="Kamaytirish">−</button><b>${row.qty}</b><button data-action="cart-plus" data-id="${p.id}" aria-label="Ko‘paytirish">+</button></div></div><label class="negotiated-price">Kelishilgan narx · 1 dona<span><input type="number" min="${allowed('priceException')?0:priceRange(p)[0]}" max="${allowed('priceException')?1e9:p.price}" step="1" data-price="${p.id}" value="${row.price}" aria-label="Kelishilgan narx: ${esc(title(p))}" required><span>so‘m</span></span></label><p class="price-note" data-price-note="${p.id}">${priceNote(row)}</p></div></div>`;}
function priceNote(row){const p=state.products.find(p=>p.id===row.productId);return `Oraliq: ${range(p)} so‘m${outsideRange(p,row.price)?' · Chegaradan tashqari, izoh kerak':''}`;}
function cartTotal(){return cart.reduce((sum,row)=>sum+row.qty*row.price,0);}
function pos(){return heading('Yangi sotuv','Modelni toping, guruhni tanlang va kelishilgan narxni yozing.',`<span class="seller-chip">Sotuvchi: ${name(user)}</span>`)+`<div class="pos-layout"><section class="catalog">${catalogFilters()}<div class="product-grid">${visibleProducts().map(productCard).join('')||empty('Mahsulot topilmadi','Model, kim uchun va g‘ilof turi filtrlarini tekshiring.')}</div></section><aside class="cart-panel panel"><div class="panel-heading"><h2>Joriy savdo <span class="count-badge">${cart.reduce((s,r)=>s+r.qty,0)}</span></h2><button class="icon-btn" data-action="clear-cart" aria-label="Savatni tozalash">${icon('trash')}</button></div><div class="cart-items">${cart.length?cart.map(cartItem).join(''):empty('Savat bo‘sh','Mahsulot guruhini tanlang.')}</div><div class="cart-bottom"><div class="cart-note">${icon('shield')}Tannarxni va katalogni faqat boshliq o‘zgartiradi</div><label class="account-selector">Pul qayerga olindi?<select id="sale-account">${options(ACCOUNTS,saleAccount)}</select></label><div class="cart-total"><span>Jami savdo</span><b id="cart-total">${money(cartTotal())}<small> so‘m</small></b></div>${button('To‘lov va yakunlash','checkout','check','primary full',cart.length?'':'disabled')}<p class="cart-footnote">Naqd, karta yoki qisman nasiya. Narxdan tashqari sotuvga sabab yoziladi.</p></div></aside></div>`;}
function inventory(){
  const rows=visibleProducts(),value=inventoryValue(state.products);
  return heading('Mahsulotlar','Model → kim uchun → g‘ilof turi → sifat. Rang va naqshlar birga sanaladi.',allowed('products')&&allowed('stock')?button('G‘iloflarni tez kiritish','case-groups')+button('Boshqa mahsulot','new-product','plus','secondary'):'')+`<div class="inventory-summary"><span><b>${state.products.length}</b> guruh</span><span><b>${state.products.reduce((s,p)=>s+stock(p),0)}</b> dona omborda</span><span class="amber"><b>${state.products.filter(p=>stock(p)<=p.min).length}</b> kam qolgan</span></div>${boss()?`<div class="inventory-values"><div><span>Ombordagi mahsulot tannarxi</span><b>${money(value.cost)} <small>so‘m</small></b></div><div><span>Yuqori narx bo‘yicha qiymati</span><b>${money(value.retail)} <small>so‘m</small></b></div><p>Sotilmagan zaxira foydadan ayrilmaydi.</p></div>`:''}<section class="panel inventory-panel">${catalogFilters()}<div class="list-toolbar">${button('Kam qoldiqlar','lowstock','alert','secondary')}${boss()?button('Kirimlar tarixi','purchase-history','download','secondary'):''}${button('CSV','export-products','download','secondary')}</div><div class="table-scroll"><table><thead><tr><th>MAHSULOT GURUHI</th><th>EGASI</th><th>NARX ORALIG‘I</th><th>QOLDIQ</th><th>AMALLAR</th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="product-cell"><span class="product-thumb">${brandMark(productIdentity(p).brand,true)}</span><div><b>${esc(title(p))}</b><small>${esc(p.name)} · ${esc(detail(p))}</small><span class="sku">${esc(p.sku)}</span></div></div></td><td>${badge(p.owner)}</td><td><b>${range(p)}</b><small>so‘m${p.minPrice===undefined?' · oraliq belgilanmagan':''}</small></td><td><span class="status ${stock(p)<=p.min?'warning':''}">${stock(p)} dona</span></td><td><div class="row-actions">${allowed('stock')?button('Kirim','purchase','plus','compact secondary',`data-id="${p.id}"`):''}${allowed('prices')?button('Narx','catalog-price','settings','compact secondary',`data-id="${p.id}"`):''}${allowed('defects')?button('Nuqson','defect','alert','compact secondary',`data-id="${p.id}"`):''}</div></td></tr>`).join('')}</tbody></table>${rows.length?'':empty('Mahsulot topilmadi')}</div></section>`;
}
function filteredSales(){const w=reportWindow(period);return state.sales.filter(s=>(boss()||s.seller===user)&&(owner==='all'||s.items.some(i=>i.owner===owner))&&(inWindow(s,w)||s.returnAt&&inWindow({at:s.returnAt},w))).slice().reverse();}
function salesTable(rows){if(!rows.length)return empty('Sotuv topilmadi','Davrni o‘zgartiring yoki yangi sotuv kiriting.');return `<div class="table-scroll"><table><thead><tr><th>CHEK / SANA</th><th>MAHSULOT</th><th>SOTUVCHI / KASSA</th><th>JAMI SAVDO</th><th>HOLATI</th><th></th></tr></thead><tbody>${rows.map(s=>{const debt=state.debts.find(d=>d.saleId===s.id);return `<tr><td><b>#${s.id}</b><small>${s.date} · ${s.time}</small></td><td><b>${esc(title(s.items[0]))}${s.items.length>1?' +'+(s.items.length-1):''}</b><small>${s.items.reduce((sum,i)=>sum+i.qty,0)} dona · ${[...new Set(s.items.map(i=>name(i.owner)))].join(', ')}</small></td><td><b>${name(s.seller)}</b><small>${s.account?accountName(s.account):s.payment+' · avvalgi yozuv'}</small></td><td><b>${money(saleTotal(s))}</b><small>so‘m</small></td><td><span class="status ${s.returned?'returned':debt?.balance?'warning':''}">${s.returned?'Qaytarilgan':debt?.balance?'Nasiya: '+money(debt.balance):'To‘langan'}</span>${s.exception?'<small class="amber">Narxdan tashqari</small>':''}</td><td><button class="icon-btn" data-action="receipt" data-id="${s.id}" aria-label="${s.id} tafsilotlari">${icon('arrow')}</button></td></tr>`;}).join('')}</tbody></table></div>`;}
function salesPage(){const rows=filteredSales().filter(s=>s.id.toLowerCase().includes(query.toLowerCase())||name(s.seller).toLowerCase().includes(query.toLowerCase())||s.items.some(i=>matchesProduct(i,query)));salesIndex=Math.min(salesIndex,Math.max(0,Math.ceil(rows.length/20)-1));return heading('Sotuvlar tarixi',boss()?'Kim nima sotdi, pul qayerga tushdi va qancha qarz qoldi.':'O‘zingiz rasmiylashtirgan sotuvlar. Boshqa sotuvchining chekini raqami bilan ham topasiz.',button('Chek raqami orqali topish','find-receipt','search','secondary'))+periodBar()+`<section class="panel"><div class="list-toolbar">${searchbar('Chek, model yoki sotuvchini qidiring…')}${button('CSV','export-sales','download','secondary')}</div>${salesTable(rows.slice(salesIndex*20,(salesIndex+1)*20))}<div class="table-foot">${rows.length} ta sotuv · ${salesIndex+1}-sahifa<div class="pagination">${button('Oldingi','sales-prev','arrow','compact secondary',salesIndex===0?'disabled':'')}${button('Keyingi','sales-next','arrow','compact secondary',(salesIndex+1)*20>=rows.length?'disabled':'')}</div></div></section>`;}
function rentPanel(){return `<section class="panel section-gap"><div class="panel-heading"><div><h2>Oylik ijara</h2><p>Oy foydasidan bir marta ayriladi. To‘lov pul harakatida alohida.</p></div>${boss()?button('Oy uchun belgilash','rent','store','secondary'):''}</div><div class="table-scroll"><table><thead><tr><th>OY / IZOH</th><th>KELISHILGAN IJARA</th><th>TO‘LANGAN</th><th>QOLDIQ</th><th></th></tr></thead><tbody>${state.rents.slice().sort((a,b)=>b.month.localeCompare(a.month)).map(r=>`<tr><td><b>${r.month}</b><small>${esc(r.note)}</small></td><td>${money(r.amount)} so‘m</td><td>${money(r.paid)} so‘m</td><td><b>${money(r.amount-r.paid)} so‘m</b></td><td>${boss()?button('Tahrirlash','rent','settings','compact secondary',`data-id="${r.id}"`):''}${r.amount>r.paid&&allowed('cash')?button('To‘lash','pay-rent','wallet','compact secondary',`data-id="${r.id}"`):'<span class="status">To‘langan</span>'}</td></tr>`).join('')}</tbody></table>${state.rents.length?'':empty('Ijara belgilanmagan','Boshliq oy va kelishilgan summani yozadi.')}</div></section>`;}
function cashPage(){
  const balances=accountBalances(state);
  const rows=state.movements.filter(m=>boss()||m.actor===user);
  const legacy=state.expenses.filter(e=>!e.ledger).map(e=>({...e,kind:'expense',actor:e.owner,account:e.payment==='Naqd'?'till1':'bank'}))
    .concat(state.purchases.map(p=>({...p,kind:'purchase',amount:p.qty*p.cost,actor:p.actor||'aziz',account:p.account||(p.payment==='Naqd'?'till1':'bank'),note:p.note||'Tovar kirimi'})));
  const needle=query.trim().toLowerCase();
  const visible=[...rows,...legacy.filter(e=>boss()||e.actor===user)]
    .filter(m=>!needle||[m.note,name(m.actor),flowName(m.kind),m.amount].join(' ').toLowerCase().includes(needle))
    .sort((a,b)=>eventTime(b)-eventTime(a));
  return heading('Kirim va chiqim','Har bir pul harakati: kim, qayerdan, qayerga va nima uchun.',button('Pul harakatini yozish','flow','plus'))+
    (boss()?`<div class="stats-grid three">${ACCOUNTS.map(([id,label])=>stat(label,balances[id],'wallet','Hisob bo‘yicha kutilayotgan qoldiq',id==='till1','so‘m',true)).join('')}</div>`:'')+
    `<div class="info-banner">${icon('shield')}<span>Xato yozuvni tafsilotidan sabab bilan bekor qiling, keyin to‘g‘risini kiriting. Eski yozuv saqlanadi; tuzatish bugungi sanada hisoblanadi.</span></div>
    <section class="panel"><div class="panel-heading"><div><h2>${boss()?'Pul harakatlari':'Men kiritgan harakatlar'}</h2><p>Sotuv, qarz to‘lovi va ijara to‘lovi ham shu yerda</p></div></div>
    <div class="list-toolbar">${searchbar('Izoh, xodim yoki summani qidiring…')}</div>
    <div class="table-scroll"><table><thead><tr><th>SANA / XODIM</th><th>AMAL / HISOB</th><th>IZOH</th><th>SUMMA / HOLAT</th><th></th></tr></thead><tbody>${visible.map(m=>`<tr>
      <td>${m.date||localDate(new Date(m.at))}<small>${name(m.actor)}</small></td>
      <td><b>${flowName(m.kind)}</b><small>${accountName(m.account)}${m.kind==='transfer'?' → '+accountName(m.to):''}${m.kind==='reimbursement'?' → '+name(m.person):''}</small></td>
      <td>${esc(m.note)}${m.reference?`<small>${esc(movementReference(m))}</small>`:''}</td>
      <td><b>${money(m.amount)} so‘m</b>${m.voidedBy?'<small class="amber">Bekor qilingan · tarixda saqlanadi</small>':m.kind==='reversal'?'<small class="green-text">Tuzatish yozuvi</small>':''}</td>
      <td>${state.movements.some(x=>x.id===m.id)?button('Tafsilot','movement-detail','receipt','compact secondary',`data-id="${esc(m.id)}"`):'<small>Avvalgi yozuv</small>'}</td>
    </tr>`).join('')}</tbody></table>${visible.length?'':empty('Harakat topilmadi')}</div></section>
    <section class="panel section-gap"><div class="panel-heading"><div><h2>Xodimga qaytariladigan pul</h2><p>O‘z cho‘ntagidan qilgan xarajatlar va kassaga qo‘shgan pul</p></div></div><div class="balance-list">${people(state).filter(u=>u.id!=='aziz'&&(boss()||u.id===user)).map(u=>`<div><span>${u.name}</span><b>${money(staffPayable(state,u.id))} so‘m</b></div>`).join('')}</div></section>${boss()?rentPanel()+closingPanel():''}`;
}
function movementReference(m){
  if(m.kind==='debt-payment')return state.debts.find(d=>d.id===m.reference)?.customer||'Qarz to‘lovi';
  if(m.kind==='rent-payment')return state.rents.find(r=>r.id===m.reference)?.month||'Ijara';
  if(m.kind==='withdrawal'&&state.closings.some(c=>c.id===m.reference))return 'Kun yakunida pul topshirish';
  return m.reference;
}
function flowName(kind){return FLOW_KINDS.find(([id])=>id===kind)?.[1]||({'sale-payment':'Sotuv to‘lovi','debt-payment':'Qarz to‘lovi',refund:'Xaridorga pul qaytarish','rent-payment':'Ijara to‘lovi',purchase:'Tovar kirimi uchun to‘lov',reversal:'Yozuvni bekor qilish'})[kind]||kind;}
function closingPanel(){
  return `<section class="panel section-gap"><div class="panel-heading"><div><h2>Kun oxiridagi kassa</h2><p>Ikkala kassadagi sanalgan pul, ertangi qaytim va topshirilgan pul.</p></div>${button('Sanash va yopish','close-day','check','secondary')}</div>
    ${state.closings.length?`<div class="table-scroll"><table><thead><tr><th>SANA</th><th>KUTILGAN / SANALGAN</th><th>FARQ</th><th>ERTANGI QAYTIM</th><th></th></tr></thead><tbody>${state.closings.slice().reverse().map(c=>`<tr><td>${c.date}<small>${esc(c.note||'Avvalgi tekshiruv')}</small></td><td>${money(c.expected)} / ${money(c.actual)}</td><td><b class="${c.actual===c.expected?'green-text':'amber'}">${money(c.actual-c.expected)}</b></td><td>${c.float===undefined?'—':money(c.float)}</td><td>${button('Tafsilot','closing-detail','receipt','compact secondary',`data-id="${esc(c.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Kassa hali sanalmagan','Har ikkala kassani sanab, ertangi qaytimni belgilang.')}</section>`;
}
function debtsPage(){requirePermission(state,user,'debts');const rows=state.debts.filter(d=>!query||[d.customer,d.phone,d.note].join(' ').toLowerCase().includes(query.toLowerCase())).slice().sort((a,b)=>(b.balance>0)-(a.balance>0)||a.due.localeCompare(b.due));return heading('Qarzdorlar','Qisman to‘lov, qolgan qarz va va’da qilingan sana — bir joyda.',boss()?button('Avvalgi qarzni kiritish','opening-debt','plus','secondary'):'')+(boss()?`<div class="stats-grid three">${stat('Jami olinadigan qarz',state.debts.reduce((s,d)=>s+d.balance,0),'wallet','Nasiya savdolaridan qolgan qism',true)}${stat('Muddat kelgan',debtReminders(state).reduce((s,d)=>s+d.balance,0),'clock',debtReminders(state).length+' ta qarz')}${stat('Ochiq qarzlar',state.debts.filter(d=>d.balance>0).length,'users','Ism va telefon bilan',false,'ta')}</div>`:'')+`<div class="info-banner">${icon('bell')}<span>Muddat kelganda platformada eslatma ko‘rinadi. Telefon xabarlari va qurilmalararo sinxronlash server bosqichida ulanadi.</span></div><section class="panel"><div class="list-toolbar">${searchbar('Ism yoki telefonni qidiring…')}</div><div class="table-scroll"><table><thead><tr><th>XARIDOR</th><th>CHEK / SABAB</th><th>MUDDAT</th><th>BOSHLANG‘ICH / QOLDIQ</th><th></th></tr></thead><tbody>${rows.map(d=>`<tr><td><b>${esc(d.customer)}</b><a class="phone-link" href="tel:${esc(d.phone.replace(/[^+\d]/g,''))}">${esc(d.phone)}</a></td><td><b>${esc(d.saleId||'Avvaldan qolgan qarz')}</b><small>${esc(d.note)}</small></td><td><span class="status ${d.balance&&d.due<=TODAY?'warning':''}">${d.due}</span></td><td>${money(d.original)}<small><b>${money(d.balance)} so‘m qoldi</b>${d.cancelledAt?' · chek qaytarilgan':''}</small></td><td>${button('Tafsilot','debt-detail','receipt','compact secondary',`data-id="${d.id}"`)}${d.balance?button('To‘lov olish','repay','wallet','compact primary',`data-id="${d.id}"`):'<span class="status">Yopilgan</span>'}</td></tr>`).join('')}</tbody></table>${rows.length?'':empty('Qarzdor yo‘q','Sotuvni yakunlashda qisman to‘lovni tanlasangiz, bu yerga tushadi.')}</div></section>`;}
function employees(){
  bossGuard();
  const persons=boss()?people(state):people(state).filter(u=>u.id===user),w=reportWindow(period);
  const rows=state.sales.filter(s=>(boss()?employee==='all'||s.seller===employee:s.seller===user)&&inWindow(s,w)).slice().reverse().flatMap(s=>s.items.map(i=>({s,i})));
  return heading(boss()?'Jamoa va sotuvlar':'Mening sotuvlarim','Sotuvchi savdosi bilan mahsulot egaligi alohida hisoblanadi.')+periodBar()+`<div class="employee-grid">${persons.map(u=>{const m=businessReport(state,{period,seller:u.id,owner:'all'});return `<section class="panel employee-card"><div class="employee-top"><span class="avatar large">${u.initials}</span><span class="status">Faol</span></div><h2>${u.name}</h2><p>${u.role}</p><div class="employee-metrics"><div><span>Cheklar</span><b>${m.count} ta</b></div><div><span>Sotilgan mahsulot</span><b>${m.units} dona</b></div><div><span>Savdo summasi</span><b>${money(m.revenue)} so‘m</b></div>${boss()?`<div><span>Sotilgan tovar tannarxi</span><b>${money(m.cogs)} so‘m</b></div><div><span>Keltirgan yalpi foyda</span><b>${money(m.gross)} so‘m</b></div>`:''}</div></section>`;}).join('')}</div><section class="panel section-gap"><div class="panel-heading"><div><h2>Kim nima va qanchaga sotdi?</h2><p>Maosh boshliq bilan kelishiladi. To‘langan maosh «Kirim va chiqim»ga yoziladi.</p></div>${boss()?`<label class="staff-select">Xodim<select id="employee-filter">${options([['all','Hammasi'],...people(state).map(u=>[u.id,u.name])],employee)}</select></label>`:''}</div><div class="table-scroll"><table><thead><tr><th>SANA / XODIM</th><th>MAHSULOT / EGASI</th><th>SONI</th><th>AMALDAGI NARX</th><th>JAMI</th>${boss()?'<th>TANNARX / YALPI FOYDA</th>':''}</tr></thead><tbody>${rows.map(({s,i})=>`<tr><td><b>${name(s.seller)}</b><small>${s.date} · ${s.id}</small></td><td><b>${esc(title(i))}</b><small>${esc(i.name)} · ${name(i.owner)}${s.returned?' · qaytarilgan':''}</small></td><td>${i.qty}</td><td><b>${money(i.price)}</b><small>Oraliq: ${i.listPrice===undefined?'—':money(i.minPrice??i.listPrice)+' – '+money(i.listPrice)}</small></td><td>${money(i.qty*i.price)}</td>${boss()?`<td>${money(i.cost)}<small>Foyda: ${s.returned?'qaytarilgan':money(i.qty*i.price-i.cost)}</small></td>`:''}</tr>`).join('')}</tbody></table>${rows.length?'':empty('Bu davrda sotuv yo‘q')}</div></section>`;
}
function reports(){bossGuard();const m=report();return heading('Hisobotlar','Yangi davr boshlansa ko‘rsatkichlar yangilanadi, avvalgi yozuvlar saqlanadi.',button('CSV yuklash','export-report','download','secondary'))+periodBar()+(!boss()?`<div class="stats-grid three">${stat('Mening savdo summam',m.revenue,'wallet','Nasiya bilan birga',true)}${stat('Mahsulotlar',m.units,'box','Qaytarishlar hisobga olingan',false,'dona')}${stat('Cheklar',m.count,'receipt','Tanlangan davr',false,'ta')}</div><div class="info-banner">${icon('shield')}<span>Tannarx va foyda hisoboti boshliq ko‘rinishida ochiladi.</span></div>`:`<div class="report-grid"><section class="panel profit-report"><div class="panel-heading"><div><h2>Foyda va zarar</h2><p>${owner==='all'?'Do‘kon bo‘yicha':name(owner)+' mahsulotlari bo‘yicha'}</p></div>${icon('chart')}</div>${[['Savdo summasi · nasiya bilan',m.revenue],['Sotilgan mahsulot tannarxi',-m.cogs],['Yalpi foyda',m.gross],['Qo‘shimcha daromad',m.income],['Kiritilgan xarajatlar',-m.expenses],['Yaroqsiz tovar zarari',-m.loss],['Oylik ijara'+(m.rentIncluded?'':' · ayrilmagan'),-m.rent]].map(([label,value],i)=>`<div class="report-line ${i===2?'subtotal':''}"><span>${label}</span><b>${money(value)} <small>so‘m</small></b></div>`).join('')}<div class="net-profit"><span>Sof natija${m.rentIncluded?'':' · ijara ayrilmagan'}</span><b>${money(m.net)} <small>so‘m</small></b></div><p class="report-hint">Faqat kiritilgan xarajatlar hisoblandi. Maosh, soliq va boshqa chiqimlar yozilganidan keyin natijaga ta’sir qiladi. Qarz to‘lovi savdo summasiga qayta qo‘shilmaydi.</p></section><section class="panel"><div class="panel-heading"><div><h2>Mahsulot egalari bo‘yicha</h2><p>Sotuvchi kimligidan qat’i nazar</p></div>${icon('users')}</div>${owners(state).map(o=>{const a=businessReport(state,{period,owner:o.id});return `<div class="owner-report"><div class="owner-report-title">${badge(o.id)}<span>${state.products.filter(p=>p.owner===o.id).reduce((s,p)=>s+stock(p),0)} dona qoldiq</span></div><div><span>Savdo summasi</span><b>${money(a.revenue)}</b></div><div><span>Sotilgan tovar tannarxi</span><b>${money(a.cogs)}</b></div><div><span>Yalpi foyda</span><b>${money(a.gross)}</b></div></div>`;}).join('')}<div class="inline-note">Boshqa egaga tegishli savdo pulini taqsimlash qoidasi hali kelishilmagan. Avtomatik hisob-kitob qilinmaydi.</div></section></div>${rentPanel()}`)+`<section class="panel section-gap"><div class="panel-heading"><div><h2>Hisobot davrlari</h2><p>Asia/Tashkent vaqti. Umumiy hisob, qoldiq, kassa va qarzlar davom etadi.</p></div></div><div class="period-rules"><span><b>Kun</b>07:00 dan</span><span><b>Hafta</b>Yakshanba 23:00 dan</span><span><b>Oy</b>1-sana 07:00 dan</span><span><b>Yil</b>31-dekabr 23:00 dan</span></div></section>`;}
function settings(){return heading('Sozlamalar','Do‘kon ma’lumoti, saqlash holati va amallar tarixi.')+`<div class="report-grid"><section class="panel settings-panel"><h2>Do‘kon ma’lumoti</h2><form id="settings-form"><label>Do‘kon nomi<input name="shop" value="${esc(state.settings.shop)}" maxlength="35" required ${boss()?'':'disabled'}></label>${boss()?'<button class="btn primary" type="submit">Saqlash</button>':'<p>Faqat boshliq o‘zgartiradi.</p>'}</form>${boss()?`<div class="section-gap">${button('Turlar va xodimlar ruxsati','nav','settings','primary','data-page="admin"')}${button('Boshlang‘ich qoldiqlar','opening-balances','wallet','secondary')}</div>`:''}<h3 class="section-gap">Ruxsatlar</h3><p>Otabek xodimlarning har bir amalini Boshqaruv bo‘limidan yoqib-o‘chiradi. Umumiy tushum, foyda va xodimlar hisobotini faqat Otabek ko‘radi.</p></section><section class="panel settings-panel"><h2>Mahalliy frontend</h2><p>Yozuvlar shu brauzer xotirasida saqlanadi. Sayt bir marta ochilgach, keshlangan interfeys internet uzilganda ham ishlaydi. ${state.operations.length} ta yangi amalga noyob ID berilgan.</p><div class="info-banner compact-info">${icon('shield')}<span>Server, haqiqiy kirish himoyasi, ikki qurilma orasidagi sinxronlash va telefon bildirishnomalari hali ulanmagan. Demo rolini almashtirish himoyalangan login emas.</span></div>${boss()?`<div class="settings-actions">${button('Zaxira nusxasini yuklash','backup','download','secondary full')}${button('Zaxiradan tiklash','restore-backup','return','secondary full')}<input id="backup-file" type="file" accept=".json,application/json" hidden>${recoverySaved()?button('Tiklashdan oldingi nusxani yuklash','recovery-backup','download','secondary full'):''}${button('Namuna ma’lumotlarini tiklash','reset','return','danger full')}</div>`:''}</section></div>${boss()?`<section class="panel section-gap"><div class="panel-heading"><div><h2>Amallar tarixi</h2><p>Yozuvlar o‘chirilmaydi; qaytarish va tuzatish alohida qayd etiladi.</p></div></div><div class="audit-list">${state.audit.slice(0,60).map(a=>`<div><span class="audit-dot"></span><span><b>${esc(a.text)}</b><small>${name(a.actor)} · ${a.date} · ${a.time}</small></span></div>`).join('')}</div></section>`:''}`;}
let modalFocus=null;
function openModal(title,body,wide=false){modalFocus=document.activeElement;modal=true;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><div><span class="eyebrow">TELEFONZONA</span><h2>${title}</h2></div><button class="icon-btn" data-action="close-modal" aria-label="Yopish">${icon('close')}</button></header><div class="modal-body">${body}</div></section></div>`;setTimeout(()=>$('#modal-root input,#modal-root select,#modal-root button')?.focus(),30);}
function openThemeModal(){
  const active=resolveTheme(document.documentElement.dataset.theme);
  openModal('O‘zingizga mos kayfiyat',`<p class="theme-intro">Ish maydoningiz, sizning uslubingiz. Ranglarni tanlang — o‘zgarishni shu zahoti ko‘rasiz.</p><div class="theme-gallery" role="group" aria-label="Interfeys mavzulari">${THEMES.map(t=>`<button type="button" class="theme-choice ${t.id===active.id?'selected':''}" data-action="theme-select" data-value="${t.id}" aria-label="${esc(t.name)} mavzusi" aria-pressed="${t.id===active.id}"><div class="theme-mini" aria-hidden="true" style="--preview-bg:${t.background};--preview-panel:${t.panel};--preview-accent:${t.accent};--preview-ink:${t.ink};--preview-side:${t.sidebar}"><span class="theme-mini-side"><i></i><i></i><i></i><i></i></span><span class="theme-mini-main"><i class="theme-mini-title"></i><span class="theme-mini-stats"><i></i><i></i><i></i></span><span class="theme-mini-table"><i></i><i></i><i></i></span></span></div><span class="theme-choice-title"><b>${esc(t.name)}</b><span class="theme-choice-status">${t.id===active.id?'Tanlangan':'Tanlash'}</span></span><p>${esc(t.description)}</p><span class="theme-swatches" aria-hidden="true">${t.colors.map(color=>`<i style="--swatch:${color}"></i>`).join('')}</span></button>`).join('')}</div><p id="theme-live-status" class="theme-live-status" role="status" aria-live="polite">${esc(active.name)} mavzusi tanlangan.</p><p class="theme-picker-footer">Tanlov shu brauzerda saqlanadi. Qurilmangizdagi «harakatni kamaytirish» sozlamasi ham hisobga olinadi.</p><div class="modal-actions">${button('Tayyor','close-modal','check','primary')}</div>`,true);
}
function closeModal(){pendingBackup=null;modal=false;$('#modal-root').innerHTML='';modalFocus?.isConnected&&modalFocus.focus();}
const field=(label,key,type='text',value='',extra='')=>`<label>${label}<input name="${key}" type="${type}" value="${esc(value)}" ${extra} required></label>`;
const select=(label,key,list,value)=>`<label>${label}<select name="${key}" required>${options(list,value)}</select></label>`;
const note=(label='Sabab / izoh',value='',required=true)=>`<label>${label}<textarea name="note" maxlength="500" rows="2" ${required?'required':''}>${esc(value)}</textarea></label>`;
const submit=(label='Saqlash')=>`<div class="form-error" role="alert"></div><div class="modal-actions"><button type="button" class="btn secondary" data-action="close-modal">Bekor qilish</button><button class="btn primary" type="submit">${icon('check')}${label}</button></div>`;
const numberExtra='min="0" max="1000000000000" step="1"';
function paymentModal(){
  requirePermission(state,user,'sell');
  if(!cart.length)return;
  const exception=cart.some(row=>outsideRange(state.products.find(p=>p.id===row.productId),row.price));
  openModal('To‘lov va yakunlash',`<form id="sale-form"><div class="inline-note">Jami savdo: <b>${money(cartTotal())} so‘m</b> · Sotuvchi: ${name(user)}</div><div class="payment-owner-review">${cart.map(row=>{const p=state.products.find(p=>p.id===row.productId);return `<div><span>${esc(title(p))} · ${row.qty} dona</span><b>Egasi: ${esc(name(p.owner))}</b></div>`;}).join('')}</div>${exception?'<div class="exception-note">Narx oralig‘idan tashqari sotuv. Sabab yoziladi va boshliqqa eslatma tushadi.</div>':''}<div class="form-grid">${select('Pul qayerga olindi?','account',ACCOUNTS,saleAccount)}${select('To‘lov holati','mode',allowed('credit')?[['full','To‘liq to‘lov'],['credit','Qisman to‘lov / nasiya']]:[['full','To‘liq to‘lov']],'full')}</div><div id="credit-fields" hidden>${field('Hozir olingan pul (so‘m)','received','number',0,numberExtra+' disabled')}<div class="form-grid">${field('Xaridor ismi','customer','text','','maxlength="80" disabled')}${field('Telefon raqami','phone','tel','','placeholder="+998 90 123 45 67" maxlength="22" disabled')}${field('Qaytarish sanasi','due','date',TODAY,`min="${TODAY}" disabled`)}</div><p class="form-help" id="debt-preview"></p></div>${note(exception?'Sabab (majburiy)':'Izoh (nasiya bo‘lsa majburiy)','',exception)}<p class="form-help">Sotuv omborni kamaytiradi. Nasiya bo‘lsa, qolgan summa qarzdorga yoziladi.</p>${submit('Sotuvni saqlash')}</form>`);
}
function caseGroupsModal(){requirePermission(state,user,'products');requirePermission(state,user,'stock');openModal('G‘iloflarni tez kiritish',`<form id="case-groups-form"><div class="form-grid">${select('Brend','brand',catalog(state).brands.map(b=>[b.id,b.name]),brand==='all'?'apple':brand)}${field('Telefon modeli','model','text','','maxlength="60" placeholder="iPhone 15 Pro yoki S23U"')}${select('Kim uchun','audience',AUDIENCES,'men')}${select('G‘ilof turi','material',catalog(state).materials,'Karbon')}${select('Mahsulot egasi','owner',owners(state).map(o=>[o.id,o.name]),'aziz')}${select('Pul qayerdan to‘landi?','account',ACCOUNTS,'till1')}</div><p class="group-entry-help">Faqat bor sifat qatorlarini to‘ldiring. Har xil rang va naqshlar shu guruh ichida birga sanaladi.</p><div class="table-scroll"><table class="group-entry-table"><thead><tr><th>SIFAT</th><th>SONI</th><th>TANNARX / DONA</th><th>ENG KAM NARX</th><th>YUQORI NARX</th></tr></thead><tbody>${catalog(state).qualities.map(t=>`<tr><td><span class="quality-badge quality-${t.id}">${esc(t.name)}</span></td>${['qty','cost','minPrice','price'].map(key=>`<td><input type="number" name="${key}-${t.id}" aria-label="${esc(t.name)}: ${{qty:'soni',cost:'tannarx',minPrice:'eng kam narx',price:'yuqori narx'}[key]}" min="${key==='minPrice'?0:1}" max="${key==='qty'?100000:1e9}" step="1" placeholder="—"></td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="form-help">Model + kim uchun + g‘ilof turi + sifat + egasi bir xil bo‘lsa, mavjud guruhga partiya qo‘shiladi. Eski tannarxlar saqlanadi.</p>${submit('Guruhlarni saqlash')}</form>`,true);}
function catalogPriceModal(id){requirePermission(state,user,'prices');const p=state.products.find(p=>p.id===id);openModal('Narx oralig‘i',`<form id="price-form" data-id="${id}"><p class="group-entry-help">${esc(title(p))} · ${name(p.owner)}</p><div class="form-grid">${field('Eng kam narx (so‘m)','minPrice','number',p.minPrice??p.price,numberExtra)}${field('Yuqori narx (so‘m)','price','number',p.price,'min="1" max="1000000000" step="1"')}</div><p class="form-help">Sotuvchi shu oraliqda savdolashadi. Sabab yozib chegaradan tashqarida ham sotishi mumkin. Avvalgi cheklar o‘zgarmaydi.</p>${submit()}</form>`);}
function purchaseModal(id){requirePermission(state,user,'stock');const p=state.products.find(p=>p.id===id);openModal('Tovar kirimi',`<form id="purchase-form" data-id="${id}"><p class="group-entry-help">${esc(title(p))} · ${name(p.owner)}</p><div class="form-grid">${field('Kelgan soni','qty','number',1,'min="1" max="100000" step="1"')}${field('Bir dona tannarxi','cost','number',cost(p),'min="1" max="1000000000" step="1"')}</div>${select('Pul qayerdan to‘landi?','account',ACCOUNTS,'till1')}${note('Kirim izohi',p.sku+' · yangi partiya')}${submit('Kirimni saqlash')}</form>`);}
function productModal(){requirePermission(state,user,'products');requirePermission(state,user,'stock');openModal('Boshqa mahsulot',`<form id="product-form"><div class="form-grid">${field('Mahsulot nomi','name','text','','maxlength="60" placeholder="Masalan: Type-C kabel"')}${field('Model / xususiyati','variant','text','','maxlength="90" placeholder="1 metr · 60W"')}${select('Brend','brand',catalog(state).brands.map(b=>[b.id,b.name]),'other')}${select('Kategoriya','category',catalog(state).categories,'Kabellar')}<label>Sifat (ixtiyoriy)<select name="quality">${options([['','Belgilanmagan'],...catalog(state).qualities.map(t=>[t.id,t.name])],'')}</select></label>${select('Mahsulot egasi','owner',owners(state).map(o=>[o.id,o.name]),'aziz')}${field('Boshlang‘ich soni','qty','number',1,'min="1" max="100000" step="1"')}${field('Bir dona tannarxi','cost','number','','min="1" max="1000000000" step="1"')}${field('Eng kam sotish narxi','minPrice','number','',numberExtra)}${field('Yuqori sotish narxi','price','number','','min="1" max="1000000000" step="1"')}${field('Kam qoldiq chegarasi','min','number',5,'min="0" max="100000" step="1"')}</div>${select('Pul qayerdan to‘landi?','account',ACCOUNTS,'till1')}${note('Kirim izohi','Boshlang‘ich kirim')}${submit('Mahsulotni qo‘shish')}</form>`,true);}
function flowModal(kind='expense'){requirePermission(state,user,'cash');openModal('Pul harakati',`<form id="flow-form">${select('Amal turi','kind',FLOW_KINDS,kind)}<div class="form-grid">${field('Summa (so‘m)','amount','number','','min="1" max="1000000000000" step="1"')}${select('Pul manbasi / hisobi','account',ACCOUNTS,'till1')}</div><div id="flow-expense">${select('Xarajat turi','category',['Boshqa','Transport','Elektr','Internet','Soliq','Maosh','Ta’mirlash'],'Boshqa')}</div><div id="flow-destination" hidden>${select('Qayerga o‘tkaziladi?','to',ACCOUNTS,'till2')}</div><div id="flow-person" hidden>${select('Kimga qaytariladi?','person',people(state).filter(u=>u.id!=='aziz').map(u=>[u.id,u.name]),'jasur')}</div>${note()}<p class="form-help" id="flow-help"></p>${submit()}</form>`);updateFlowForm();}
function updateFlowForm(){const form=$('#flow-form');if(!form)return;const kind=form.elements.kind.value,old=form.elements.account.value;form.elements.account.innerHTML=options(kind==='expense'?[...ACCOUNTS,['personal','O‘z cho‘ntagimdan']]:ACCOUNTS,old);$('#flow-expense').hidden=kind!=='expense';$('#flow-destination').hidden=kind!=='transfer';$('#flow-person').hidden=kind!=='reimbursement';$('#flow-help').textContent=({expense:'Xarajat foydadan ayriladi. O‘z pulingizdan bo‘lsa, do‘konning sizga qarzi ham yoziladi.',income:'Faqat haqiqiy qo‘shimcha daromad uchun. Bu sof natijaga qo‘shiladi.',contribution:'Kassaga shaxsiy pul qo‘shish daromad emas. Xodim pul qo‘shsa, do‘konning unga qarzi yoziladi.',withdrawal:'Boshliqqa pul topshirish — pul harakati. Xarajat va foyda emas.',transfer:'Pul hisoblar orasida ko‘chadi. Foydaga ta’sir qilmaydi.',reimbursement:'Xodim o‘zidan qilgan xarajat / qo‘shgan pulini qaytarish. Foydadan qayta ayrilmaydi.'})[kind];}
function rentModal(id){if(!boss())throw Error('Faqat boshliq uchun.');const r=state.rents.find(r=>r.id===id);openModal('Oylik ijara',`<form id="rent-form">${field('Qaysi oy uchun','month','month',r?.month||TODAY.slice(0,7))}${field('Kelishilgan oylik summa (so‘m)','amount','number',r?.amount??'',numberExtra)}${note('Izoh / kelishuv',r?.note||'')}<p class="form-help">Bu summa shu oy foydasidan bir marta ayriladi. Kunlik / haftalik natijaga ijara taqsimlanmaydi. Haqiqiy to‘lov alohida yoziladi.</p>${submit('Ijarani belgilash')}</form>`);}
function rentPaymentModal(id){requirePermission(state,user,'cash');const r=state.rents.find(r=>r.id===id);openModal('Ijara to‘lovi',`<form id="rent-payment-form" data-id="${id}"><div class="inline-note">${r.month} uchun qoldiq: <b>${money(r.amount-r.paid)} so‘m</b></div>${field('Hozir to‘lanadigan summa','amount','number',r.amount-r.paid,`min="1" max="${r.amount-r.paid}" step="1"`)}${select('Qayerdan to‘lanadi?','account',[...ACCOUNTS,['personal','O‘z cho‘ntagimdan']],'bank')}${note('To‘lov izohi',r.month+' oyi ijara to‘lovi')}<p class="form-help">Kassa / bank qoldig‘i kamayadi. Foydadan ikkinchi marta ayrilmaydi.</p>${submit('To‘lovni saqlash')}</form>`);}
function repayModal(id){requirePermission(state,user,'debts');const d=state.debts.find(d=>d.id===id);openModal('Qarz to‘lovini olish',`<form id="repay-form" data-id="${id}"><div class="inline-note">${esc(d.customer)} · ${esc(d.phone)}<br>Qolgan qarz: <b>${money(d.balance)} so‘m</b></div>${field('Olingan summa','amount','number',d.balance,`min="1" max="${d.balance}" step="1"`)}${select('Pul qayerga olindi?','account',ACCOUNTS,'till1')}${note('To‘lov izohi','Qarzning bir qismi / to‘liq qaytdi')}<p class="form-help">Savdo summasiga qayta qo‘shilmaydi. Qarz kamayadi, pul qoldig‘i oshadi.</p>${submit('To‘lovni saqlash')}</form>`);}
function debtDetail(id){requirePermission(state,user,'debts');const d=state.debts.find(d=>d.id===id);openModal('Qarz tafsilotlari',`<div class="receipt-top"><h3>${esc(d.customer)}</h3><p>${esc(d.phone)} · muddat ${d.due}</p><b>${money(d.balance)} so‘m qoldi</b></div><p class="panel-copy">${esc(d.note)}</p><div class="balance-list"><div><span>Boshlang‘ich qarz</span><b>${money(d.original)}</b></div>${d.payments.map(p=>`<div><span>${p.date} · ${name(p.actor)}<small>${accountName(p.account)} · ${esc(p.note)}${p.voidedBy?' · Bekor qilingan':''}</small></span><b>−${money(p.amount)}</b></div>`).join('')}${d.cancelledAt?`<div><span>Chek qaytarilishi sabab bekor qilingan</span><b>${money(d.cancelled)}</b></div>`:''}</div><div class="modal-actions">${d.saleId?button('Chekni ko‘rish','receipt','receipt','secondary',`data-id="${d.saleId}"`):''}${d.balance?button('To‘lov olish','repay','wallet','primary',`data-id="${d.id}"`):''}</div>`);}
function receiptModal(id){const s=state.sales.find(s=>s.id===id);if(!s)return;const d=state.debts.find(d=>d.saleId===id);openModal('Sotuv tafsilotlari',`<div class="receipt-top"><div class="receipt-symbol">${icon(s.returned?'return':'check')}</div><h3>${s.returned?'Sotuv qaytarilgan':'Sotuv saqlandi'}</h3><p>#${s.id} · ${s.date} · ${s.time}</p></div><div class="receipt-meta"><span>Sotuvchi <b>${name(s.seller)}</b></span><span>Pul hisobi <b>${s.account?accountName(s.account):s.payment}</b></span></div>${s.items.map(i=>`<div class="receipt-line"><div><b>${esc(title(i))}</b><small>${esc(i.name)} · ${name(i.owner)}</small><small>${i.qty} × ${money(i.price)} so‘m · amaldagi narx</small>${i.listPrice===undefined?'':`<small>O‘sha paytdagi oraliq: ${money(i.minPrice??i.listPrice)} – ${money(i.listPrice)}</small>`}</div><b>${money(i.qty*i.price)}</b></div>`).join('')}<div class="cart-total"><span>Jami savdo</span><b>${money(saleTotal(s))}<small> so‘m</small></b></div><div class="receipt-meta"><span>Sotuvda olingan pul <b>${money(s.received??saleTotal(s))} so‘m</b></span>${d?`<span>Qolgan qarz <b>${money(d.balance)} so‘m</b></span>`:''}${boss()?`<span>Tannarx <b>${money(s.items.reduce((sum,i)=>sum+i.cost,0))} so‘m</b></span><span>Yalpi foyda${s.returned?' · qaytarilgan':''} <b>${money(saleProfit(s))} so‘m</b></span>`:''}</div>${s.note?`<div class="inline-note">Izoh: ${esc(s.note)}</div>`:''}${s.returned?`<div class="inline-note">Qaytargan: ${name(s.returnActor||'aziz')} · ${s.returnDate}<br>${esc(s.returnNote||'Avvalgi to‘liq qaytarish')}</div>`:''}<div class="modal-actions">${!s.returned&&allowed('returns')?button('Qaytarish / almashtirish','return','return','danger',`data-id="${id}"`):''}${button('Yopish','close-modal','check','primary')}</div>`);}
function returnModal(id){requirePermission(state,user,'returns');const s=state.sales.find(s=>s.id===id),d=state.debts.find(d=>d.saleId===id),collected=(s.received??saleTotal(s))+(d?.payments.filter(p=>!p.voidedBy).reduce((sum,p)=>sum+p.amount,0)||0);openModal('Qaytarish / almashtirish',`<form id="return-form" data-id="${id}"><div class="inline-note">#${id} cheki to‘liq qaytariladi. Barcha mahsulotlari omborga qaytadi.<br>Qaytariladigan pul: <b>${money(collected)} so‘m</b>${d?.balance?`<br>Bekor qilinadigan qarz: ${money(d.balance)} so‘m`:''}</div>${select('Pul qayerdan qaytariladi?','account',ACCOUNTS,s.account||'till1')}${note('Qaytarish sababi')}<p class="form-help">Almashtirishda shu chekni qaytaring, so‘ng yangi mahsulotga yangi sotuv yozing. Yaroqsiz qaytgan mahsulotni keyin «Nuqson» orqali belgilang. Qisman qaytarish hali qo‘shilmagan.</p>${submit('To‘liq qaytarishni saqlash')}</form>`);}
function defectModal(id){requirePermission(state,user,'defects');const p=state.products.find(p=>p.id===id);openModal('Nuqsonli mahsulot',`<form id="defect-form" data-id="${id}"><p class="group-entry-help">${esc(title(p))} · qoldiq ${stock(p)} dona</p>${select('Holati','kind',[['dispose','Yaroqsiz — hisobdan chiqarish'],['repair','Tuzatib sotiladi — ta’mir xarajati']],'dispose')}<div id="defect-dispose">${field('Hisobdan chiqariladigan soni','qty','number',1,`min="1" max="${stock(p)}" step="1"`)}</div><div id="defect-repair" hidden>${field('Ta’mirlash xarajati','amount','number','','min="1" max="1000000000" step="1" disabled')}${select('To‘lov manbasi','account',[...ACCOUNTS,['personal','O‘z cho‘ntagimdan']],'till1')}</div>${note('Nima bo‘ldi?')}<p class="form-help">Yaroqsiz tovar tannarxi bir marta zararga yoziladi. Ta’mirda soni o‘zgarmaydi; xarajat yoziladi, so‘ng savdoda arzonroq narxni sabab bilan kiriting.</p>${submit()}</form>`);}
function movementModal(id){
  const m=state.movements.find(m=>m.id===id);if(!m||!boss()&&m.actor!==user)throw Error('Bu yozuvni ko‘rish huquqi yo‘q.');
  const original=m.kind==='reversal'?state.movements.find(x=>x.id===m.reversalOf):null;
  openModal('Pul harakati tafsilotlari',`<div class="receipt-top"><h3>${flowName(m.kind)}</h3><p>${dateLabel(m.at)} · ${name(m.actor)}</p><b>${money(m.amount)} so‘m</b></div>
    <div class="receipt-meta"><span>Pul hisobi <b>${accountName(m.account)}${m.to?' → '+accountName(m.to):''}${m.person?' → '+name(m.person):''}</b></span></div>
    <div class="inline-note">Izoh: ${esc(m.note)}</div>
    ${original?`<div class="inline-note">Bekor qilingan amal: ${flowName(original.kind)} · ${dateLabel(original.at)}<br>${esc(original.note)}</div>`:''}
    ${m.voidedBy?`<div class="exception-note">${name(m.voidedActor)} tomonidan ${dateLabel(m.voidedAt)} da bekor qilingan.<br>Sabab: ${esc(m.voidedReason)}</div>`:''}
    <div class="modal-actions">${canReverseMovement(m,user,state)?button('Xato yozuvni bekor qilish','reverse-movement','return','danger',`data-id="${id}"`):''}${m.kind==='sale-payment'||m.kind==='refund'?button('Chekni ko‘rish','receipt','receipt','secondary',`data-id="${esc(m.reference)}"`):''}${button('Yopish','close-modal','check','secondary')}</div>`);
}
function reverseModal(id){
  const m=state.movements.find(m=>m.id===id);if(!canReverseMovement(m,user,state))throw Error('Bu yozuvni bekor qilib bo‘lmaydi.');
  openModal('Xato pul yozuvini bekor qilish',`<form id="reverse-form" data-id="${id}"><div class="inline-note"><b>${flowName(m.kind)} · ${money(m.amount)} so‘m</b><br>${name(m.actor)} · ${accountName(m.account)}<br>${esc(m.note)}</div>${note('Nima uchun bekor qilinyapti?')}
    <p class="form-help">Eski yozuv o‘chmaydi. Tuzatish hozirgi sana bilan yoziladi; kassa, qarz yoki xodimga qaytariladigan pul mos ravishda o‘zgaradi. Keyin kerak bo‘lsa to‘g‘ri yozuvni kiriting.</p>${submit('Bekor qilishni saqlash')}</form>`);
}
function closingModal(){
  bossGuard();const b=accountBalances(state);
  openModal('Kun oxiridagi kassa',`<form id="closing-form"><div class="inline-note">Kutilgan jami naqd: <b>${money(b.till1+b.till2)} so‘m</b><br>1-kassa: ${money(b.till1)} · 2-kassa: ${money(b.till2)}</div>
    <div class="form-grid">${field('1-kassada sanalgan','till1','number','',numberExtra)}${field('2-kassada sanalgan','till2','number','',numberExtra)}${field('1-kassada qoladigan qaytim','float1','number',0,numberExtra)}${field('2-kassada qoladigan qaytim','float2','number',0,numberExtra)}</div>
    ${select('Boshliqqa pul topshirish','handover',[['no','Hozir faqat sanashni saqlash'],['yes','Pulni berdim — topshirishni ham yozish']],'no')}
    <div id="closing-preview" class="closing-preview" aria-live="polite">Ikkala kassada sanalgan pulni yozing.</div>
    ${note('Sanash / farq izohi','Kun yakuni')}
    <p class="form-help">Topshirishni tanlasangiz, sanalgan puldan qaytim ayrilib, har bir kassadan boshliqqa berilgan summa alohida yoziladi. Sanashdagi farq daromad yoki xarajatga yashirincha qo‘shilmaydi.</p>${submit('Kun yakunini saqlash')}</form>`,true);
}
function updateClosingPreview(){
  const form=$('#closing-form');if(!form)return;
  const values=Object.fromEntries(['till1','till2','float1','float2'].map(key=>[key,form.elements[key].value.trim()===''?NaN:Number(form.elements[key].value)]));
  if(Object.values(values).some(n=>!Number.isSafeInteger(n)||n<0)){$('#closing-preview').textContent='Ikkala kassadagi pul va qaytimni butun so‘mda yozing.';return;}
  if(values.float1>values.till1||values.float2>values.till2){$('#closing-preview').textContent='Qaytim o‘sha kassada sanalgan puldan oshmasin.';return;}
  const b=accountBalances(state),actual=values.till1+values.till2,remaining=values.float1+values.float2,difference=actual-b.till1-b.till2,handover=form.elements.handover.value==='yes';
  $('#closing-preview').innerHTML=`<div><span>Sanalgan jami</span><b>${money(actual)} so‘m</b></div><div><span>Sanashdagi farq</span><b class="${difference?'amber':'green-text'}">${difference>0?'+':''}${money(difference)} so‘m</b></div><div><span>Ertangi qaytim · jami</span><b>${money(remaining)} so‘m</b></div><div><span>${handover?'Hozir topshiriladi':'Topshirilishi mumkin'}</span><b>${money(actual-remaining)} so‘m</b></div>${handover?`<small>1-kassadan ${money(values.till1-values.float1)}, 2-kassadan ${money(values.till2-values.float2)} so‘m. ${difference?'Sanashdagi farq tekshirish uchun saqlanadi.':'Hisobda ham aynan qaytim puli qoladi.'}</small>`:'<small>Hozir pul harakati yozilmaydi; faqat sanash saqlanadi.</small>'}`;
}
function closingDetail(id){
  bossGuard();const c=state.closings.find(c=>c.id===id);if(!c)throw Error('Kassa sanog‘i topilmadi.');
  const withdrawals=(c.withdrawalIds||[]).map(id=>state.movements.find(m=>m.id===id)).filter(Boolean);
  openModal('Kassa yakuni tafsilotlari',`<p class="group-entry-help">${c.date} · ${name(c.actor||'aziz')}<br>${esc(c.note||'Avvalgi sanash')}</p>
    <div class="balance-list"><div><span>Hisob bo‘yicha jami</span><b>${money(c.expected)}</b></div><div><span>Sanalgan jami</span><b>${money(c.actual)}</b></div><div><span>Farq</span><b class="${c.actual===c.expected?'green-text':'amber'}">${money(c.actual-c.expected)}</b></div>${c.expectedAccounts?['till1','till2'].map((id,index)=>`<div><span>${accountName(id)} · hisob / sanalgan</span><b>${money(c.expectedAccounts[id])} / ${money(c[id])}</b></div><div><span>${accountName(id)} · ertangi qaytim</span><b>${money(c[index?'float2':'float1']??0)}</b></div>`).join(''):`<div><span>Ertangi qaytim</span><b>${c.float===undefined?'—':money(c.float)}</b></div>`}</div>
    <h3>Topshirilgan pul</h3>${withdrawals.length?withdrawals.map(m=>`<div class="receipt-line"><span>${accountName(m.account)}<small>${m.voidedBy?'Keyin bekor qilingan':'Boshliqqa topshirilgan'}</small></span><b>${money(m.amount)} so‘m</b></div>`).join(''):'<p class="group-entry-help">Bu sanash bilan pul topshirish yozilmagan.</p>'}<div class="modal-actions">${button('Yopish','close-modal','check','secondary')}</div>`);
}
function recoverySaved(){try{return !!localStorage.getItem(RECOVERY_KEY);}catch{return false;}}
async function loadBackupFile(file){
  try{
    bossGuard();if(!file)return;if(file.size>MAX_BACKUP_BYTES)throw Error('Zaxira fayli 8 MB dan oshmasin.');
    const next=readBackup(await file.text());bossGuard();
    const incoming=backupSummary(next),current=backupSummary(state);
    pendingBackup={state:next,name:file.name,baseRaw:localStorage.getItem(KEY)};
    openModal('Zaxirani tekshirish',`<p class="group-entry-help">Fayl: <b>${esc(file.name)}</b><br>Fayl tekshirildi. Quyidagi raqamlarni solishtiring.</p>
      <div class="table-scroll"><table class="backup-comparison"><thead><tr><th>MA’LUMOT</th><th>HOZIR</th><th>FAYLDA</th></tr></thead><tbody>${[['Mahsulot guruhlari','products'],['Omborda dona','units'],['Cheklar','sales'],['Pul harakatlari','movements'],['Xaridorlardan qarz','debt']].map(([label,key])=>`<tr><td>${label}</td><td>${money(current[key])}</td><td>${money(incoming[key])}</td></tr>`).join('')}${ACCOUNTS.map(([id,label])=>`<tr><td>${label}</td><td>${money(current.balances[id])}</td><td>${money(incoming.balances[id])}</td></tr>`).join('')}</tbody></table></div>
      <div class="exception-note">Tiklash ushbu brauzerdagi joriy ma’lumotni fayldagi ma’lumot bilan almashtiradi. Hozirgi nusxa tiklashdan oldin alohida saqlanadi va Sozlamalardan yuklab olinadi. Joriy savat tozalanadi.</div>
      <div class="modal-actions">${button('Bekor qilish','close-modal','close','secondary')}${button('Tekshirdim — zaxiradan tiklash','confirm-restore','check','primary')}</div>`,true);
  }catch(error){toast(error.message);}
  finally{const input=$('#backup-file');if(input)input.value='';}
}
function restoreBackup(){
  bossGuard();if(!pendingBackup)throw Error('Avval zaxira faylini tanlang.');
  const currentRaw=localStorage.getItem(KEY);
  if(currentRaw!==pendingBackup.baseRaw)throw Error('Fayl ko‘rilayotgan paytda boshqa oynada ma’lumot o‘zgardi. Zaxira faylini qayta tanlab solishtiring.');
  const next=structuredClone(pendingBackup.state);
  next.operations.push({id:uid(),actor:user,kind:'backup-restore',at:new Date().toISOString(),status:'local'});
  log(next,user,'Zaxira faylidan tiklandi: '+pendingBackup.name);
  try{if(currentRaw!==null)localStorage.setItem(RECOVERY_KEY,currentRaw);localStorage.setItem(KEY,JSON.stringify(next));}
  catch{throw Error('Brauzerda zaxira nusxasi uchun joy yetmadi yoki saqlash yopilgan. Joriy ma’lumot almashtirilmadi.');}
  state=next;loadFailed=false;storedRaw=null;cart=[];pendingBackup=null;closeModal();navigate('settings');toast('Zaxiradan tiklandi. Tiklashdan oldingi nusxa ham saqlandi.');
}
function notifications(){const reminders=allowed('debts')?debtReminders(state):[];openModal('Eslatmalar',`${reminders.map(d=>`<div class="notification-item"><b>${esc(d.customer)} · ${money(d.balance)} so‘m qarz</b><p>${d.due} · ${esc(d.phone)}</p>${button('To‘lov olish','repay','wallet','compact secondary',`data-id="${d.id}"`)}</div>`).join('')}${boss()?state.notices.slice(0,30).map(n=>`<div class="notification-item"><b>${esc(n.text)}</b><p>${name(n.actor)} · ${dateLabel(n.at)}</p></div>`).join(''):''}${!reminders.length&&(!boss()||!state.notices.length)?empty('Yangi eslatma yo‘q','Qarz muddati va xodim amallari shu yerga tushadi.'):''}`);if(boss()&&state.notices.some(n=>!n.read))mutate(d=>{d.notices.forEach(n=>n.read=true);});}
function purchaseHistory(){if(!boss())throw Error('Faqat boshliq uchun.');openModal('Tovar kirimlari',`<div class="table-scroll"><table><thead><tr><th>SANA / MAHSULOT</th><th>SONI</th><th>TANNARX</th><th>JAMI / MANBA</th></tr></thead><tbody>${state.purchases.slice().reverse().map(p=>`<tr><td>${p.date}<small>${esc(title(state.products.find(x=>x.id===p.productId)))}</small></td><td>${p.qty}</td><td>${money(p.cost)}</td><td>${money(p.qty*p.cost)}<small>${accountName(p.account|| (p.payment==='Naqd'?'till1':'bank'))}</small></td></tr>`).join('')}</tbody></table>${state.purchases.length?'':empty('Yangi kirim yozilmagan','Boshlang‘ich namuna qoldiqlari tarixiy kirim to‘lovi hisoblanmaydi.')}</div>`,true);}
function openingBalancesModal(){bossGuard();openModal('Boshlang‘ich qoldiqlar',`<form id="opening-balances-form"><p class="group-entry-help">Hisob yuritish boshlanishidan oldingi pulni kiriting. Keyingi sotuv va chiqimlar shu summaga qo‘shib hisoblanadi. Bugungi sanalgan pulni bu yerga yozmang — «Kunni yopish»dan foydalaning.</p><div class="form-grid">${ACCOUNTS.map(([id,label])=>field(label+' · boshlang‘ich',id,'number',state.settings.openingAccounts[id],numberExtra)).join('')}${['jasur','sardor'].map(id=>field(name(id)+'ga avvaldan qarz',id,'number',state.settings.openingPayables?.[id]||0,numberExtra)).join('')}</div>${note('Boshlang‘ich hisob izohi')}${submit()}</form>`);}
function openingDebtModal(){bossGuard();openModal('Avvaldan qolgan qarz',`<form id="opening-debt-form"><p class="group-entry-help">Tizimga o‘tishdan oldingi qarz. Yangi savdo va foyda hisoblanmaydi.</p><div class="form-grid">${field('Xaridor ismi','customer','text','','maxlength="80"')}${field('Telefon raqami','phone','tel','','maxlength="22" placeholder="+998 90 123 45 67"')}${field('Qolgan qarz','amount','number','','min="1" max="1000000000000" step="1"')}${field('Qaytarish sanasi','due','date',TODAY)}</div>${note('Qarz nima uchun qolgan?')}${submit()}</form>`);}
function download(filename,text,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([type.includes('csv')?'\uFEFF':'',text],{type})),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(rows){return rows.map(row=>row.map(value=>'"'+String(value??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');}
function resetCatalog(){catalogOwner='all';brand='all';series='all';quality='all';audience='all';material='all';query='';category='all';}
function navigate(target){if(!canVisit(state,user,target))throw Error('Bu bo‘lim Otabek tomonidan ruxsat etilmagan.');page=Object.hasOwn(pages,target)?target:'dashboard';resetCatalog();salesIndex=0;closeModal();render();window.scrollTo({top:0});}
function bossGuard(){if(!boss())throw Error('Bu ma’lumotlarni faqat boshliq o‘zgartiradi.');}
document.addEventListener('pointerdown',event=>{
  if(event.button!==0||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  const target=event.target.closest('.btn,.theme-trigger,.theme-choice,.nav-item,.brand-card,.product-card');
  if(!target||target.disabled)return;
  const rect=target.getBoundingClientRect(),size=Math.hypot(rect.width,rect.height)*2;
  const ripple=document.createElement('span');ripple.className='touch-ripple';ripple.setAttribute('aria-hidden','true');
  Object.assign(ripple.style,{width:size+'px',height:size+'px',left:event.clientX-rect.left-size/2+'px',top:event.clientY-rect.top-size/2+'px'});
  target.append(ripple);setTimeout(()=>ripple.remove(),600);
});
document.addEventListener('click',event=>{
  const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();const id=el.dataset.id,value=el.dataset.value;
  try{switch(el.dataset.action){
    case 'themes':openThemeModal();break;
    case 'theme-select':{const result=chooseTheme(value);if(!result.persisted)toast('Mavzu o‘zgardi. Brauzer xotirasiga saqlab bo‘lmadi.');break;}
    case 'nav':navigate(el.dataset.page);break;
    case 'period':period=value;salesIndex=0;render();break;
    case 'brand':brand=value;series='all';query='';render();break;
    case 'series':series=value;query='';render();$('#search')?.focus();break;
    case 'category':category=value;render();break;
    case 'catalog-reset':resetCatalog();render();break;
    case 'lowstock':navigate('inventory');category='low';render();break;
    case 'find-product':{const p=state.products.find(p=>p.id===id);navigate('inventory');query=p.sku;render();break;}
    case 'case-groups':caseGroupsModal();break;
    case 'new-product':productModal();break;
    case 'catalog-price':catalogPriceModal(id);break;
    case 'purchase':purchaseModal(id);break;
    case 'purchase-history':purchaseHistory();break;
    case 'defect':defectModal(id);break;
    case 'add-cart':addCart(id);break;
    case 'cart-minus':cart.find(r=>r.productId===id).qty--;cart=cart.filter(r=>r.qty);render();break;
    case 'cart-plus':addCart(id);break;
    case 'clear-cart':cart=[];render();break;
    case 'checkout':if([...document.querySelectorAll('[data-price]')].every(i=>i.reportValidity()))paymentModal();break;
    case 'receipt':receiptModal(id);break;
    case 'find-receipt':openModal('Chekni topish',`<form id="find-receipt-form">${field('Chek raqami','receipt','text','','placeholder="S-1123" maxlength="40"')}${submit('Topish')}</form>`);break;
    case 'return':returnModal(id);break;
    case 'sales-prev':salesIndex=Math.max(0,salesIndex-1);render();break;
    case 'sales-next':salesIndex++;render();break;
    case 'flow':flowModal();break;
    case 'movement-detail':movementModal(id);break;
    case 'reverse-movement':reverseModal(id);break;
    case 'closing-detail':closingDetail(id);break;
    case 'restore-backup':bossGuard();$('#backup-file').click();break;
    case 'confirm-restore':restoreBackup();break;
    case 'recovery-backup':bossGuard();download(`telefonzona-tiklashdan-oldin-${TODAY}.json`,localStorage.getItem(RECOVERY_KEY)||'{}','application/json');break;
    case 'opening-balances':openingBalancesModal();break;
    case 'opening-debt':openingDebtModal();break;
    case 'rent':rentModal(id);break;
    case 'pay-rent':rentPaymentModal(id);break;
    case 'repay':repayModal(id);break;
    case 'debt-detail':debtDetail(id);break;
    case 'notifications':notifications();break;
    case 'close-day':closingModal();break;
    case 'close-modal':closeModal();break;
    case 'backup':bossGuard();download(`telefonzona-${TODAY}.json`,loadFailed?storedRaw:JSON.stringify(state,null,2),'application/json');break;
    case 'reset':bossGuard();openModal('Namuna ma’lumotlarini tiklash',`<p>Shu brauzerga kiritilgan amallar o‘chadi va namuna qaytadi. Kerak bo‘lsa avval zaxira nusxasini oling.</p><div class="modal-actions">${button('Bekor qilish','close-modal','close','secondary')}${button('Tiklash','do-reset','return','danger')}</div>`);break;
    case 'do-reset':bossGuard();loadFailed=false;mutate(d=>Object.assign(d,prepareState(makeSeed())));cart=[];closeModal();render();toast('Namuna tiklandi.');break;
    case 'export-products':download('telefonzona-mahsulotlar.csv',csv([['SKU','Mahsulot','Kim uchun','G‘ilof turi','Sifat','Egasi','Qoldiq','Eng kam narx','Yuqori narx'],...visibleProducts().map(p=>[p.sku,title(p),audienceName(p.audience),p.material,qualityLabel(p.quality),name(p.owner),stock(p),p.minPrice??'',p.price])]));break;
    case 'export-sales':download('telefonzona-sotuvlar.csv',csv([['Chek','Sana','Sotuvchi','Hisob','Mahsulot','Egasi','Soni','Amaldagi narx','Jami','Izoh','Holati'],...filteredSales().flatMap(s=>s.items.map(i=>[s.id,s.date,name(s.seller),s.account||s.payment,title(i),name(i.owner),i.qty,i.price,i.qty*i.price,s.note,s.returned?'Qaytarilgan':'Sotilgan']))]));break;
    case 'export-report':{bossGuard();const m=report();download('telefonzona-hisobot.csv',csv(boss()?[['Hisobot','Qiymat'],['Davr',period],['Savdo',m.revenue],['Tannarx',m.cogs],['Yalpi foyda',m.gross],['Qo‘shimcha daromad',m.income],['Xarajat',m.expenses],['Nuqson zarari',m.loss],['Ijara',m.rent],['Sof natija',m.net],['Ijara hisoblandi',m.rentIncluded?'Ha':'Yo‘q']]:[['Hisobot','Qiymat'],['Davr',period],['Sotuvchi',name(user)],['Savdo',m.revenue],['Soni',m.units],['Cheklar',m.count]]));break;}
  }}catch(error){toast(error.message);}
});
document.addEventListener('input',event=>{
  const input=event.target;
  if(input.dataset.price){
    const value=Number(input.value),p=state.products.find(p=>p.id===input.dataset.price),valid=input.value.trim()!==''&&Number.isSafeInteger(value)&&value>=0&&value<=1e9&&(allowed('priceException')||!outsideRange(p,value));
    input.setCustomValidity(valid?'':'Narxni butun so‘mda va ruxsat etilgan oraliqda kiriting.');
    if(valid){cart.find(r=>r.productId===input.dataset.price).price=value;$('#cart-total').innerHTML=money(cartTotal())+'<small> so‘m</small>';document.querySelectorAll('[data-price-note]').forEach(p=>p.textContent=priceNote(cart.find(r=>r.productId===p.dataset.priceNote)));}return;
  }
  if(input.id==='search'){query=input.value;salesIndex=0;const position=input.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(position,position);}
  if(input.closest('#closing-form'))updateClosingPreview();
  if(input.name==='received'&&$('#debt-preview'))$('#debt-preview').textContent='Qoladigan qarz: '+money(Math.max(0,cartTotal()-Number(input.value)))+' so‘m';
});
document.addEventListener('change',event=>{
  const input=event.target;
  if(input.dataset.cartOwner){try{cart=selectCartOwner(state,cart,input.dataset.cartOwner,input.value,user);render();}catch(error){render();toast(error.message);}return;}
  if(input.id==='backup-file'){void loadBackupFile(input.files?.[0]);return;}
  if(input.closest('#closing-form'))updateClosingPreview();
  if(input.id==='role'){user=input.value;owner='all';cart=[];navigate(boss()?'dashboard':allowed('sell')?'pos':'dashboard');toast(name(user)+' demo ko‘rinishi.');}
  else if(input.id==='owner-filter'){owner=input.value;render();}
  else if(input.id==='catalog-owner'){catalogOwner=input.value;render();}
  else if(input.id==='audience-filter'){audience=input.value;render();}
  else if(input.id==='material-filter'){material=input.value;render();}
  else if(input.id==='quality-filter'){quality=input.value;render();}
  else if(input.id==='employee-filter'){employee=input.value;render();}
  else if(input.id==='sale-account')saleAccount=input.value;
  else if(input.name==='mode'&&input.closest('#sale-form')){
    const credit=input.value==='credit';$('#credit-fields').hidden=!credit;$('#credit-fields').querySelectorAll('input').forEach(i=>i.disabled=!credit);
    const exception=cart.some(r=>outsideRange(state.products.find(p=>p.id===r.productId),r.price));$('#sale-form [name="note"]').required=credit||exception;
    $('#debt-preview').textContent='Qoladigan qarz: '+money(cartTotal())+' so‘m';
  }
  else if(input.name==='kind'&&input.closest('#flow-form'))updateFlowForm();
  else if(input.name==='kind'&&input.closest('#defect-form')){
    const repair=input.value==='repair';$('#defect-dispose').hidden=repair;$('#defect-dispose input').disabled=repair;$('#defect-repair').hidden=!repair;$('#defect-repair input').disabled=!repair;
  }
});
document.addEventListener('submit',event=>{
  event.preventDefault();const form=event.target,data=Object.fromEntries(new FormData(form));
  const num=key=>{if(String(data[key]??'').trim()==='')throw Error('Raqamli maydonlarni to‘ldiring.');const n=Number(data[key]);if(!Number.isSafeInteger(n)||n<0||n>1e12)throw Error('Raqamlarni tekshiring.');return n;};
  try {
    let receipt=null;
    switch(form.matches('.catalog-option-form')?'catalog-option-form':form.matches('.staff-permissions-form')?'staff-permissions-form':form.id){
      case 'catalog-option-form':mutate(d=>addCatalogOption(d,form.dataset.kind,data.name,user));break;
      case 'staff-permissions-form':mutate(d=>saveStaffPermissions(d,form.dataset.person,data.name,Object.fromEntries(PERMISSIONS.map(p=>[p.id,form.elements[p.id].checked])),user));break;
      case 'find-receipt-form':{const receiptId=data.receipt.trim().replace(/^#/, '').toUpperCase();if(!state.sales.some(s=>s.id===receiptId))throw Error('Bu raqamdagi chek topilmadi.');receiptModal(receiptId);return;}
      case 'sale-form':{
        const received=data.mode==='credit'?num('received'):cartTotal();
        receipt=mutate(d=>recordSale(d,cart,user,{...data,received}));cart=[];saleAccount=data.account;break;
      }
      case 'case-groups-form':{
        requirePermission(state,user,'products');requirePermission(state,user,'stock');const rows=catalog(state).qualities.flatMap(t=>{const values=['qty','cost','minPrice','price'].map(key=>String(data[key+'-'+t.id]||'').trim());if(!values.some(v=>v!==''))return [];if(values.some(v=>v===''))throw Error('Tanlangan sifat uchun soni, tannarx va ikkala narxni to‘ldiring.');return [{quality:t.id,qty:Number(values[0]),cost:Number(values[1]),minPrice:Number(values[2]),price:Number(values[3])}];});
        mutate(d=>registerCaseGroups(d,{...data,payment:data.account==='bank'?'Karta':'Naqd',rows},user));page='inventory';resetCatalog();query=data.model;break;
      }
      case 'price-form':requirePermission(state,user,'prices');mutate(d=>setCatalogPrice(d,form.dataset.id,num('price'),user,num('minPrice')));break;
      case 'purchase-form':requirePermission(state,user,'stock');mutate(d=>{purchase(d,form.dataset.id,num('qty'),num('cost'),data.account==='bank'?'Karta':'Naqd',user);Object.assign(d.purchases.at(-1),{account:data.account,note:data.note});});break;
      case 'product-form':mutate(d=>registerProduct(d,{...data,price:num('price'),minPrice:num('minPrice'),min:num('min'),qty:num('qty'),cost:num('cost')},user));break;
      case 'opening-balances-form':bossGuard();mutate(d=>setOpeningBalances(d,Object.fromEntries(ACCOUNTS.map(([id])=>[id,num(id)])),{jasur:num('jasur'),sardor:num('sardor')},user,data.note));break;
      case 'opening-debt-form':bossGuard();mutate(d=>addOpeningDebt(d,{...data,amount:num('amount')},user));break;
      case 'flow-form':mutate(d=>recordFlow(d,{...data,amount:num('amount')},user));break;
      case 'rent-form':bossGuard();mutate(d=>setRent(d,data.month,num('amount'),data.note,user));break;
      case 'rent-payment-form':mutate(d=>payRent(d,form.dataset.id,num('amount'),data.account,user,data.note));break;
      case 'repay-form':mutate(d=>repayDebt(d,form.dataset.id,num('amount'),data.account,user,data.note));break;
      case 'return-form':mutate(d=>returnSale(d,form.dataset.id,user,data.account,data.note));break;
      case 'defect-form':requirePermission(state,user,'defects');mutate(d=>{if(data.kind==='dispose')disposeStock(d,form.dataset.id,num('qty'),data.note,user);else recordFlow(d,{kind:'expense',category:'Ta’mirlash',account:data.account,amount:num('amount'),note:form.dataset.id+' · '+data.note},user);});break;
      case 'closing-form':bossGuard();mutate(d=>closeDay(d,{till1:num('till1'),till2:num('till2'),float1:num('float1'),float2:num('float2'),handover:data.handover==='yes',note:data.note},user));break;
      case 'reverse-form':mutate(d=>reverseMovement(d,form.dataset.id,user,data.note));break;
      case 'settings-form':bossGuard();if(!data.shop.trim())throw Error('Do‘kon nomini yozing.');mutate(d=>{d.settings.shop=data.shop.trim();log(d,user,'Do‘kon nomi yangilandi');});break;
      default:return;
    }
    closeModal();render();if(receipt)receiptModal(receipt.id);toast('Shu brauzerga saqlandi. Hisoblar yangilandi.');
  }catch(error){const output=form.querySelector('.form-error');if(output)output.textContent=error.message;else toast(error.message);}
});
document.addEventListener('keydown',event=>{
  if(event.key==='Escape')closeModal();
  if(event.key==='Tab'&&modal){const list=[...document.querySelectorAll('.modal button,.modal input,.modal select,.modal textarea')].filter(el=>!el.disabled&&el.getClientRects().length);if(event.shiftKey&&document.activeElement===list[0]){event.preventDefault();list.at(-1)?.focus();}else if(!event.shiftKey&&document.activeElement===list.at(-1)){event.preventDefault();list[0]?.focus();}}
});
